def coalesce(intervals):
    result = []
    try:
        iterator = iter(intervals)
    except Exception as exc:
        raise ValueError("intervals must be iterable") from exc

    for interval in iterator:
        try:
            values = tuple(interval)
        except Exception as exc:
            raise ValueError("each interval must contain exactly two integers") from exc
        if len(values) != 2 or any(type(value) is not int for value in values):
            raise ValueError("each interval must contain exactly two integers")
        start, end = values
        if start >= end:
            raise ValueError("interval start must be less than end")
        result.append((start, end))

    result.sort()
    merged = []
    for start, end in result:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged
